            if ident > high:
                high = ident
            if open_tx:
                pending.append(('put', ident))
        elif op == 'delete':
            ident = action.get('id')
            if ident in rows:
                rows.remove(ident)
            if open_tx:
                pending.append(('delete', ident))
        elif op == 'begin':
            open_tx = True
            pending = []
        elif op == 'commit':
            open_tx = False
            pending = []
        elif op == 'rollback':
            for item in reversed(pending):
                kind = item[0]
                ident = item[1]
                if kind == 'put':
                    if ident in rows:
                        rows.remove(ident)
                else:
                    rows.append(ident)
            open_tx = False
            pending = []
    return high + 1

