    actions = context.get('actions', [])
    committed = set()
    pending = None
    high = 0
    for action in actions:
        op = action.get('op')
        if op == 'begin':
            pending = set(committed)
        elif op == 'commit':
            committed = pending
            pending = None
        elif op == 'rollback':
            pending = None
