    events = context.get('events', [])
    decoder = None
    count = 0
    status = 'open'
    for event in events:
        op = event.get('op')
        if op == 'feed':
            data = bytes(event.get('bytes', []))
            try:
                text = decoder.decode(data, False)
            except UnicodeDecodeError:
                status = 'error'
            else:
                count += len(text)
        elif op == 'finish':
            try:
                text = decoder.decode(b'', True)
            except UnicodeDecodeError:
                status = 'error'
            else:
                count += len(text)
                status = 'finished'
        elif op == 'reset':
            decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            count = 0
            status = 'open'
    return {'count': count, 'status': status}

